227	/// Find the project root by walking up from current directory.
228	///
229	/// Looks for:
230	/// 1. `.bivvy` directory (primary indicator)
231	/// 2. `.git` directory (fallback)
232	///
233	/// # Returns
234	///
235	/// The path to the project root, or None if not found.
236	pub fn find_project_root(start: &Path) -> Option<PathBuf> {
237	    let mut current = start.to_path_buf();
238	
239	    loop {
240	        // Check for .bivvy directory
241	        if current.join(".bivvy").is_dir() {
242	            return Some(current);
243	        }
244	
245	        // Check for .git directory (fallback)
246	        if current.join(".git").exists() {
247	            return Some(current);
248	        }
249	
250	        // Move up one directory
251	        if !current.pop() {
252	            return None;
253	        }
254	    }
255	}
