466	/// Load every workflow file in `paths`, parse each as `WorkflowFile`
467	/// (with legacy fallback), and produce one merged partial config value.
468	fn load_split_workflow_files_all(paths: &[PathBuf]) -> Result<Option<serde_yaml::Value>> {
469	    if paths.is_empty() {
470	        return Ok(None);
471	    }
472	
473	    let partials: Vec<serde_yaml::Value> = paths
474	        .iter()
475	        .map(|path| {
476	            let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
477	                BivvyError::ConfigParseError {
478	                    path: path.clone(),
479	                    message: "Could not determine name from filename".to_string(),
480	                }
481	            })?;
482	            let file = load_single_workflow_file(path)?;
483	            workflow_file_to_partial(&file, stem)
484	        })
485	        .collect::<Result<Vec<_>>>()?;
486	
487	    Ok(Some(merge_configs(&partials)))
488	}
