25	
26	/// What the user asked to lint.
27	enum LintTarget {
28	    /// Bare invocation or `--config`: lint `.bivvy/config.yml` only.
29	    ProjectConfig,
30	    /// `--workflow <name>` or positional that resolved to a workflow file.
31	    WorkflowFile(String),
32	    /// `--step <name>` or positional that resolved to a step file.
33	    StepFile(String),
34	    /// `--all`: full merged config (legacy behavior).
35	    All,
36	}
37	
38	/// The lint command implementation.
39	pub struct LintCommand {
40	    project_root: PathBuf,
41	    args: LintArgs,
42	    config_override: Option<PathBuf>,
43	}
44	
45	impl LintCommand {
46	    /// Create a new lint command.
47	    pub fn new(project_root: &Path, args: LintArgs) -> Self {
48	        Self {
49	            project_root: project_root.to_path_buf(),
50	            args,
51	            config_override: None,
52	        }
53	    }
54	
55	    /// Set an override config path.
56	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
57	        self.config_override = config_override;
58	        self
59	    }
60	
61	    /// Get the project root path.
62	    pub fn project_root(&self) -> &Path {
63	        &self.project_root
64	    }
65	
66	    /// Get the command arguments.
67	    pub fn args(&self) -> &LintArgs {
68	        &self.args
69	    }
70	
71	    /// Run all lint rules and collect diagnostics.
72	    fn run_rules(
73	        &self,
74	        registry: &RuleRegistry,
75	        config: &crate::config::BivvyConfig,
76	    ) -> Vec<LintDiagnostic> {
77	        let mut diagnostics = Vec::new();
78	        for rule in registry.iter() {
79	            diagnostics.extend(rule.check(config));
80	        }
81	        diagnostics
82	    }
83	
84	    /// Resolve which target the user asked to lint.
85	    fn resolve_target(&self) -> Result<LintTarget> {
86	        if self.config_override.is_some() {
87	            // Explicit config file override: lint just that file via load_config.
88	            return Ok(LintTarget::ProjectConfig);
89	        }
90	        if let Some(ref name) = self.args.workflow {
91	            return Ok(LintTarget::WorkflowFile(name.clone()));
92	        }
93	        if let Some(ref name) = self.args.step {
94	            return Ok(LintTarget::StepFile(name.clone()));
95	        }
96	        if self.args.all {
97	            return Ok(LintTarget::All);
98	        }
99	        if self.args.config_only {
100	            return Ok(LintTarget::ProjectConfig);
101	        }
102	        if let Some(ref name) = self.args.target {
103	            let discovery = Discovery::new(&self.project_root);
104	            if discovery.workflow_path(name).is_some() {
105	                if discovery.step_path(name).is_some() {
106	                    // Both exist (rare) — pick workflow but surface a hint.
107	                    return Ok(LintTarget::WorkflowFile(name.clone()));
108	                }
109	                return Ok(LintTarget::WorkflowFile(name.clone()));
110	            }
111	            if discovery.step_path(name).is_some() {
112	                return Ok(LintTarget::StepFile(name.clone()));
113	            }
114	            return Err(BivvyError::ConfigValidationError {
115	                message: format!(
116	                    "Unknown lint target: {name}. No file found at \
117	                     .bivvy/workflows/{name}.yml or .bivvy/steps/{name}.yml"
118	                ),
119	            });
120	        }
121	        Ok(LintTarget::ProjectConfig)
122	    }
123	
124	    /// Build the [`BivvyConfig`] view to lint plus the source paths it draws from.
125	    fn build_target_config(&self, target: &LintTarget) -> Result<(BivvyConfig, Vec<PathBuf>)> {
126	        if let Some(ref override_path) = self.config_override {
127	            // Explicit override: just load that file in isolation.
128	            let cfg = load_config(&self.project_root, Some(override_path))?;
129	            return Ok((cfg, vec![override_path.clone()]));
130	        }
131	
132	        match target {
133	            LintTarget::ProjectConfig => {
134	                let cfg = load_project_config(&self.project_root)?;
135	                let path = self.project_root.join(".bivvy").join("config.yml");
136	                Ok((cfg, vec![path]))
137	            }
138	            LintTarget::WorkflowFile(name) => {
139	                let discovery = Discovery::new(&self.project_root);
140	                let workflow_path =
141	                    discovery
142	                        .workflow_path(name)
143	                        .ok_or_else(|| BivvyError::ConfigNotFound {
144	                            path: self
145	                                .project_root
146	                                .join(".bivvy")
147	                                .join("workflows")
148	                                .join(format!("{name}.yml")),
149	                        })?;
