//! Detection of unknown fields in raw YAML configuration.
//!
//! Structs like `Settings` and `StepConfig` use `#[serde(flatten)]`, which
//! is incompatible with serde's `deny_unknown_fields`. This module fills
//! that gap by walking the raw YAML value tree and comparing keys against
//! known fields, returning warnings for anything unrecognized.

use serde_yaml::Value;

/// A warning about an unrecognized field in config YAML.
#[derive(Debug, Clone)]
pub struct UnknownFieldWarning {
    /// Dotted path to the field, e.g. "settings.paralle".
    pub path: String,
    /// The unrecognized key.
    pub field: String,
    /// Closest known field name, if one is close enough.
    pub suggestion: Option<String>,
}

impl std::fmt::Display for UnknownFieldWarning {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if let Some(ref suggestion) = self.suggestion {
            write!(
                f,
                "unknown field '{}' in config (did you mean '{}'?)",
                self.path, suggestion
            )
        } else {
            write!(f, "unknown field '{}' in config", self.path)
        }
    }
}

// Known fields for `settings:` (flattened from LoggingSettings,
// ExecutionSettings, EnvVarSettings, EnvironmentProfileSettings, plus own).
const SETTINGS_FIELDS: &[&str] = &[
    // LoggingSettings
    "logging",
    "log_retention_days",
    "log_retention_mb",
    // ExecutionSettings
    "parallel",
    "max_parallel",
    "history_retention",
    "diagnostic_funnel",
    "auto_update",
    "default_rerun_window",
    // EnvVarSettings
    "env",
    "env_file",
    "secret_env",
    // EnvironmentProfileSettings
    "default_environment",
    "environments",
    // Own field
    "defaults",
];

// Known fields for step definitions (flattened from ExecutionConfig,
// EnvironmentVarsConfig, BehaviorConfig, HookConfig, StepOutputSettings,
// EnvironmentScopingConfig, plus own fields and aliases).
const STEP_FIELDS: &[&str] = &[
    // StepConfig own fields
    "template",
    "inputs",
    "title",
    "description",
    "depends_on",
    "tools",
    "requires",         // alias for tools
    "satisfied_when",
    "watches",          // deprecated, accepted for compat
    // ExecutionConfig
    "command",
    "check",
    "completed_check",  // alias for check
    "checks",
    "precondition",
    "retry",
    "requires_sudo",
    // EnvironmentVarsConfig
    "env",
    "env_file",
    "env_file_optional",
    "required_env",
    // BehaviorConfig
    "skippable",
    "required",
    "confirm",
    "auto_run",
    "prompt_on_rerun",
    "prompt_if_complete", // alias for prompt_on_rerun
    "allow_failure",
    "sensitive",
    "rerun_window",
    "force",
    // HookConfig
    "before",
    "after",
    // StepOutputSettings
    "output",
    "prompts",
    // EnvironmentScopingConfig
    "environments",
    "only_environments",
];

// Known fields for `settings.defaults:`.
const DEFAULTS_FIELDS: &[&str] = &["output", "auto_run", "prompt_on_rerun", "rerun_window"];

// Known fields for workflow definitions.
const WORKFLOW_FIELDS: &[&str] = &[
    "description",
    "steps",
    "overrides",
    "settings",
    "force",
    "force_all",
];

/// Check a merged YAML config value for unrecognized fields.
///
/// Walks the `settings`, `steps`, and `workflows` sections, comparing
/// keys against the known field sets. Returns a warning for each
/// unrecognized key, with a suggestion when a close match exists.
pub fn check_unknown_fields(value: &Value) -> Vec<UnknownFieldWarning> {
    let mut warnings = Vec::new();

    let Some(root) = value.as_mapping() else {
        return warnings;
    };

    // Check settings fields
    if let Some(settings) = root
        .get(Value::String("settings".into()))
        .and_then(|v| v.as_mapping())
    {
        check_mapping(settings, SETTINGS_FIELDS, "settings", &mut warnings);

        // Check settings.defaults fields
        if let Some(defaults) = settings
            .get(Value::String("defaults".into()))
            .and_then(|v| v.as_mapping())
        {
            check_mapping(
                defaults,
                DEFAULTS_FIELDS,
                "settings.defaults",
                &mut warnings,
            );
        }
    }

    // Check step fields
    if let Some(steps) = root
        .get(Value::String("steps".into()))
        .and_then(|v| v.as_mapping())
    {
        for (key, step_value) in steps {
            let step_name = key.as_str().unwrap_or("<unknown>");
            if let Some(step_map) = step_value.as_mapping() {
                check_mapping(
                    step_map,
                    STEP_FIELDS,
                    &format!("steps.{}", step_name),
                    &mut warnings,
                );
            }
        }
    }

    // Check workflow fields
    if let Some(workflows) = root
        .get(Value::String("workflows".into()))
        .and_then(|v| v.as_mapping())
    {
        for (key, wf_value) in workflows {
            let wf_name = key.as_str().unwrap_or("<unknown>");
            if let Some(wf_map) = wf_value.as_mapping() {
                check_mapping(
                    wf_map,
                    WORKFLOW_FIELDS,
                    &format!("workflows.{}", wf_name),
                    &mut warnings,
                );
            }
        }
    }

    warnings
}

/// Check all keys in a mapping against a set of known fields.
fn check_mapping(
    mapping: &serde_yaml::Mapping,
    known: &[&str],
    parent_path: &str,
    warnings: &mut Vec<UnknownFieldWarning>,
) {
    for key in mapping.keys() {
        let Some(field) = key.as_str() else {
            continue;
        };
        if !known.contains(&field) {
            let suggestion = closest_match(field, known);
            warnings.push(UnknownFieldWarning {
                path: format!("{}.{}", parent_path, field),
                field: field.to_string(),
                suggestion,
            });
        }
    }
}

/// Find the closest known field by edit distance, if one is close enough.
fn closest_match(input: &str, candidates: &[&str]) -> Option<String> {
    let mut best: Option<(&str, usize)> = None;

    for &candidate in candidates {
        let dist = edit_distance(input, candidate);
        if let Some((_, best_dist)) = best {
            if dist < best_dist {
                best = Some((candidate, dist));
            }
        } else {
            best = Some((candidate, dist));
        }
    }

    // Only suggest if the distance is at most ~40% of the longer string.
    best.and_then(|(candidate, dist)| {
        let max_len = input.len().max(candidate.len());
        let threshold = (max_len / 3).max(2);
        if dist <= threshold {
            Some(candidate.to_string())
        } else {
            None
        }
    })
}

/// Simple Levenshtein edit distance.
fn edit_distance(a: &str, b: &str) -> usize {
    let a_bytes = a.as_bytes();
    let b_bytes = b.as_bytes();
    let m = a_bytes.len();
    let n = b_bytes.len();

    let mut prev = (0..=n).collect::<Vec<_>>();
    let mut curr = vec![0; n + 1];

    for i in 1..=m {
        curr[0] = i;
        for j in 1..=n {
            let cost = if a_bytes[i - 1] == b_bytes[j - 1] {
                0
            } else {
                1
            };
            curr[j] = (prev[j] + 1)
                .min(curr[j - 1] + 1)
                .min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    prev[n]
}

